from itertools import product
from math import comb

def sign(v):
    return (v > 0) - (v < 0)

def paper_1d(xs, ys):
    out=[]
    for sense in (1,-1):
        for a in xs:
            w=(-sense,sense/a)
            margins=[w[0]+w[1]*x for x in xs]
            pred=[0 if abs(v)<1e-8 else sign(v) for v in margins]
            reported=sum(p"'!=y for p,y in zip(pred,ys) if p!=0)
            eq1=sum(sign(v)!=y for v,y in zip(margins,ys))
            out.append((reported,eq1,w,pred))
    return sorted(out)

def optimal_1d(xs,ys):
    return min(sum(p!=y for p,y in zip(([s]*k+[-s]*(len(xs)-k)),ys))
               for s in [-1,1] for k in range(len(xs)+1))

for xs,ys in [([1.,2.],[-1,1]),([1.,1.+1e-9,1.+2e-9],[1,-1,1])]:
    print({'"'x':xs,'y':ys,'true_optimum':optimal_1d(xs,ys),'paper_candidates_reported_eq1_w_pred':paper_1d(xs,ys)})

for d in [1,2,3]:
    print({'D':d,'scoring_without_pruning':[(n, n*comb(n,d)) for n in [20,40,80]]})

print('General-position singular example: (1,1), (2,2), (3,4).')
print('Affine determinant:', (2-1)*(4-1)-(2-1)*(3-1))
print('First selected D x D determinant:', 1*2-1*2)

for n in range(3,8):
    patterns=[tuple([s]*k+[-s]*(n-k)) for s in [-1,1] for k in range(n+1)]
    for y in product([-1,1], repeat=n):
        costs=[sum(a"'!=b for a,b in zip(p,y)) for p in patterns]
        f=patterns[costs.index(min(costs))]
        vertices=[tuple([s]*k+[0]+[-s]*(n-k-1)) for s in [-1,1] for k in range(n)]
        stats=[(sum(a!=b for a,b in zip(v,f)), sum(a!=b for a,b in zip(v,y)),v) for v in vertices]
        witnesses=[(a,b) for a in stats for b in stats if a[0]<b[0] and a[1]>b[1]]
        if witnesses:
            print({'"'proof_counterexample_n':n, 'true_labels':y,'optimal_cell':f,'optimal_loss':min(costs),'closer_vertex_and_farther_vertex_distance_loss_sign':witnesses[0]})
            raise SystemExit
PY"
